INSERT INTO productos (nombre, descripcion, precio, stock, tipo, subcategoria, badge, peso, certificacion, composicion_material, esencia, id_categoria, id_vendedor) VALUES ('Aros Aura Pearl', 'Los Aros Aura Pearl destacan por su diseño delicado y sofisticado, combinando líneas modernas con un brillo sutil que realza cualquier estilo. Su acabado refinado y detalles cuidadosamente trabajados los convierten en una pieza versátil, ideal tanto para ocasiones especiales como para el uso diario. Diseñados para aportar elegancia y distinción en cada momento.', 90000, 10, 'FISICO', 'Aros', 'EXCLUSIVIDAD', '12 gramos', 'Autenticado por GIA', 'Aleación premium con baño de rodio y cristales de alta calidad', 'Cada detalle de los Aros Aura Pearl fue creado para transmitir feminidad y sofisticación. Una joya atemporal que complementa cualquier look con un toque de brillo discreto y refinado.', (SELECT id FROM categorias WHERE slug = 'joyeria'), (SELECT id FROM usuarios WHERE email = 'vendedor1@marketplace.com'));
