INSERT INTO productos (nombre, descripcion, precio, stock, tipo, subcategoria, badge, peso, certificacion, composicion_material, esencia, id_categoria, id_vendedor) VALUES ('Lingote de Oro Laminado', 'El Lingote de Oro representa una inversión sólida y una pieza de gran prestigio. Su acabado brillante y presentación impecable reflejan pureza, exclusividad y valor duradero, convirtiéndolo en una elección ideal para coleccionistas e inversionistas.', 2300000, 10, 'FISICO', 'Lingotes de Oro', NULL, '100 gramos', 'Autenticado por GIA', 'Oro Laminado', 'El Lingote de Oro Laminado representa prestigio, exclusividad y valor. Su acabado brillante y su diseño inspirado en lingotes de inversión lo convierten en una pieza ideal para coleccionistas y amantes del lujo.', (SELECT id FROM categorias WHERE slug = 'lingotes'), (SELECT id FROM usuarios WHERE email = 'vendedor1@marketplace.com'));
