INSERT INTO productos (nombre, descripcion, precio, stock, tipo, subcategoria, badge, peso, certificacion, composicion_material, esencia, id_categoria, id_vendedor) VALUES ('Reloj Imperial', 'El reloj Imperial combina sofisticación clásica y diseño contemporáneo en una pieza exclusiva. Su esfera negra con detalles dorados y numeración romana aporta presencia y distinción, mientras que la correa de cuero texturizado brinda comodidad y un acabado refinado. Diseñado para quienes valoran la elegancia atemporal y los detalles de lujo en cada ocasión.', 200000, 10, 'FISICO', 'Exclusivo', 'EXCLUSIVIDAD', '55 Gramos', 'Autenticado por GIA', 'Cuero premium', 'Cada detalle del reloj Imperial fue diseñado para reflejar sofisticación, precisión y carácter. Una pieza atemporal que combina materiales premium, acabados refinados y un estilo pensado para destacar en cualquier momento.', (SELECT id FROM categorias WHERE slug = 'edicion-limitada'), (SELECT id FROM usuarios WHERE email = 'vendedor1@marketplace.com'));
